"""The Pads window: the VJ's pad surface (native/pads.py) - the banks along the top, the grid of controls drawn below
and played with the mouse or a touchscreen, and an Edit mode: a cell clicked picks it, a control dragged moves it, its
corner resizes it, and the panel beside the grid sets what it is and what it drives.

    show(app)          # the window (the VJ frame's Pads... button)
    poll(app)          # each frame: the grid drawn and played (app.py's main loop)
"""
# AI: below section was generated by an AI
import dearpygui.dearpygui as dpg

from native.typeface import px
from native import form, num, pads

TAG = "pads_win"
GRID = "pads_grid"
SIDE = "pads_side"
SIDE_W = 270
KNOB_PX = 160                  # a knob turned from bottom to top by dragging this far up
HANDLE = 12                    # the resize corner of a selected control, in pixels at 1x


def _c():
    from native import chrome
    return chrome


def _st(app):
    """The project's pads, made whole once for each project (and after an undo)."""
    o = app.project.options.get("pads")
    if o is None or getattr(app, "_pads_whole", None) is not o:
        o = pads.state(app.project)
        app._pads_whole = o
    return o


def _save(app):
    app.project.save()


# --- the window -------------------------------------------------------------------------------------------------
def build(app):
    c = _c()
    with dpg.window(tag=TAG, show=False, no_title_bar=True, no_collapse=True, width=px(720), height=px(620),
                    no_scrollbar=True):
        c.dialog_header(TAG, "Pads", on_close=lambda: _close(app))
        with dpg.group(horizontal=True):
            dpg.add_group(tag="pads_banks", horizontal=True)
            dpg.add_button(label="+", tag="pads_addbank", small=True, callback=lambda: _add_bank(app))
            c.tip("a new bank of pads (an empty 4 x 4 grid)")
            dpg.add_checkbox(label="Edit", tag="pads_edit", callback=lambda s, v: _set_edit(app, v))
            c.tip("lay the bank out: click a cell to add a control or pick one, drag a control to move it, its corner "
                  "to resize it; the panel sets what it is and what it drives. Pads do nothing while editing")
        with dpg.group(horizontal=True, tag="pads_bankrow", show=False):
            dpg.add_input_text(tag="pads_bname", width=px(130), hint="bank name", on_enter=False,
                               callback=lambda s, v: _bank_set(app, "name", v.strip() or "Bank"))
            dpg.add_combo([n for n, _ in pads.COLOURS], tag="pads_bcolour", width=px(80),
                          callback=lambda s, v: _bank_set(app, "colour", v))
            c.tip("the bank button's colour")
            form.inline("columns")
            num.add("pads_cols", 4, pads.GRID_MIN, pads.GRID_MAX, integer=True, width=px(60),
                    callback=lambda s, v: _grid_size(app, cols=v))
            form.inline("rows")
            num.add("pads_rows", 4, pads.GRID_MIN, pads.GRID_MAX, integer=True, width=px(60),
                    callback=lambda s, v: _grid_size(app, rows=v))
            dpg.add_button(label="<", small=True, callback=lambda: _move_bank(app, -1))
            c.tip("this bank one to the left")
            dpg.add_button(label=">", small=True, callback=lambda: _move_bank(app, 1))
            c.tip("this bank one to the right")
            dpg.add_button(label="Copy", small=True, callback=lambda: _copy_bank(app))
            c.tip("a copy of this bank after it")
            dpg.add_button(label="Delete", tag="pads_delbank", small=True, callback=lambda: _delete_bank(app))
            c.tip("this bank and its controls gone (Undo brings it back)")
            dpg.add_button(label="Undo", small=True, callback=lambda: _undo(app))
            c.tip("the pads' last change undone")
        with dpg.group(horizontal=True):
            with dpg.child_window(tag="pads_area", border=False, width=-1, height=-1, no_scrollbar=True):
                dpg.add_drawlist(tag=GRID, width=px(400), height=px(400))
            with dpg.child_window(tag=SIDE, width=px(SIDE_W), height=-1, show=False, border=True):
                _build_side(app)


def _build_side(app):
    c = _c()
    dpg.add_text("", tag="pads_s_title", color=c.ACCENT)
    with dpg.group(tag="pads_s_empty"):
        dpg.add_text("An empty cell. Add:", color=c.DIM)
        for typ in pads.TYPES:
            dpg.add_button(label=pads.TYPE_WORDS[typ], width=-1, user_data=typ,
                           callback=lambda s, a, u: _add_control(app, u))
    with dpg.group(tag="pads_s_ctl", show=False):
        dpg.add_combo([pads.TYPE_WORDS[t] for t in pads.TYPES], tag="pads_s_type", width=-1,
                      callback=lambda s, v: _ctl_set(app, "type", next(t for t in pads.TYPES if pads.TYPE_WORDS[t] == v)))
        dpg.add_input_text(tag="pads_s_label", width=-1, hint="label (the action's name if empty)",
                           callback=lambda s, v: _ctl_set(app, "label", v))
        dpg.add_combo([n for n, _ in pads.COLOURS], tag="pads_s_colour", width=-1,
                      callback=lambda s, v: _ctl_set(app, "colour", v))
        dpg.add_text("DRIVES", color=c.ACCENT)
        dpg.add_text("", tag="pads_s_target", wrap=px(SIDE_W - 20))
        dpg.add_input_text(tag="pads_s_find", width=-1, hint="find an action",
                           callback=lambda s, v: _fill_actions(app))
        dpg.add_listbox([], tag="pads_s_actions", width=-1, num_items=8,
                        callback=lambda s, v: _pick_action(app, v))
        with dpg.group(tag="pads_s_lookrow", show=False):
            dpg.add_combo([], tag="pads_s_look", width=-1, callback=lambda s, v: _target_set(app, look=v))
        with dpg.group(tag="pads_s_presetrow", show=False):
            dpg.add_combo([], tag="pads_s_preset", width=-1, callback=lambda s, v: _target_set(app, name=v))
        with dpg.group(tag="pads_s_valrow"):
            dpg.add_text("RANGE", color=c.ACCENT)
            with form.row("from", width=px(50)):
                num.add("pads_s_lo", 0.0, 0.0, 1.0, digits=3, width=-1,
                        callback=lambda s, v: _ctl_set(app, "lo", round(v, 3)))
            with form.row("to", width=px(50)):
                num.add("pads_s_hi", 1.0, 0.0, 1.0, digits=3, width=-1,
                        callback=lambda s, v: _ctl_set(app, "hi", round(v, 3)))
            c.tip("a button sets the target to 'to' (and back to 'from' for a toggle or a hold); a fader or a knob "
                  "moves it between the two")
            dpg.add_checkbox(label="upside down", tag="pads_s_invert", callback=lambda s, v: _ctl_set(app, "invert", v))
        dpg.add_combo(["vertical", "horizontal"], tag="pads_s_orient", width=-1,
                      callback=lambda s, v: _ctl_set(app, "orient", "v" if v == "vertical" else "h"))
        c.tip("which way a fader moves")
        dpg.add_button(label="Remove this control", width=-1, callback=lambda: _remove_control(app))


def show(app):
    from native import chrome
    if not dpg.does_item_exist(TAG):
        build(app)
    chrome._centre(TAG, 720, 620)
    dpg.show_item(TAG)
    app._pads_labels = None
    _fill_banks(app)
    _fill_side(app)


def _close(app):
    pads.let_go(app)
    dpg.hide_item(TAG)


# --- banks -------------------------------------------------------------------------------------------------------
def _fill_banks(app):
    st = _st(app)
    dpg.delete_item("pads_banks", children_only=True)
    for i, b in enumerate(st["banks"]):
        tag = f"pads_bank{i}"
        dpg.add_button(label=b["name"], tag=tag, parent="pads_banks", user_data=i,
                       callback=lambda s, a, u: switch_bank(app, u))
        dpg.bind_item_theme(tag, _bank_theme(b["colour"], i == st["bank"]))
    edit = bool(getattr(app, "_pads_edit", False))
    dpg.configure_item("pads_bankrow", show=edit)
    b = pads.current(st)
    dpg.set_value("pads_bname", b["name"])
    dpg.set_value("pads_bcolour", b["colour"])
    num.set("pads_cols", b["cols"])
    num.set("pads_rows", b["rows"])
    dpg.configure_item("pads_delbank", enabled=len(st["banks"]) > 1)


_THEMES = {}


def _bank_theme(colour, on):
    key = (colour, on)
    if key not in _THEMES:
        r, g, b = pads.COLOUR.get(colour, pads.COLOUR["grey"])
        k = 1.0 if on else 0.35
        with dpg.theme() as t:
            with dpg.theme_component(dpg.mvButton):
                dpg.add_theme_color(dpg.mvThemeCol_Button, (int(r * k), int(g * k), int(b * k), 255))
                dpg.add_theme_color(dpg.mvThemeCol_ButtonHovered, (int(r * min(1, k + .2)), int(g * min(1, k + .2)),
                                                                   int(b * min(1, k + .2)), 255))
                dpg.add_theme_color(dpg.mvThemeCol_Text, (10, 10, 12, 255) if on else (230, 232, 236, 255))
        _THEMES[key] = t
    return _THEMES[key]


def switch_bank(app, i):
    """The grid shows bank i - the picture on the LEDs is not touched."""
    st = _st(app)
    if not 0 <= i < len(st["banks"]) or i == st["bank"]:
        return
    pads.let_go(app)
    st["bank"] = i
    app._pads_sel = None
    _save(app)
    _fill_banks(app)
    _fill_side(app)


def _add_bank(app):
    st = _st(app)
    if len(st["banks"]) >= pads.MAX_BANKS:
        app.gp.status(f"pads: {pads.MAX_BANKS} banks at most", "warn"); return
    st["banks"].append(pads.new_bank(f"Bank {len(st['banks']) + 1}", colour=pads.COLOURS[len(st["banks"]) % 11 + 1][0]))
    switch_bank(app, len(st["banks"]) - 1)
    _save(app)


def _bank_set(app, key, v):
    pads.current(_st(app))[key] = v
    _save(app)
    _fill_banks(app)


def _grid_size(app, cols=None, rows=None):
    b = pads.current(_st(app))
    if not pads.resize_grid(b, b["cols"] if cols is None else cols, b["rows"] if rows is None else rows):
        app.gp.status("pads: a control is in the way - move or remove it first", "warn")
    _save(app)
    _fill_banks(app)


def _move_bank(app, d):
    st = _st(app)
    i, j = st["bank"], st["bank"] + d
    if 0 <= j < len(st["banks"]):
        st["banks"][i], st["banks"][j] = st["banks"][j], st["banks"][i]
        st["bank"] = j
        _save(app)
        _fill_banks(app)


def _copy_bank(app):
    st = _st(app)
    if len(st["banks"]) >= pads.MAX_BANKS:
        app.gp.status(f"pads: {pads.MAX_BANKS} banks at most", "warn"); return
    switch_bank(app, pads.copy_bank(st, st["bank"]))
    _save(app)


def _delete_bank(app):
    st = _st(app)
    if len(st["banks"]) <= 1:
        return
    pads.let_go(app)
    st["banks"].pop(st["bank"])
    st["bank"] = max(0, st["bank"] - 1)
    app._pads_sel = None
    _save(app)
    _fill_banks(app)
    _fill_side(app)


def _undo(app):
    pads.let_go(app)
    if not app.project.undo("pads"):
        app.gp.status("nothing to undo in the pads"); return
    app._pads_whole = None
    app._pads_sel = None
    _fill_banks(app)
    _fill_side(app)


# --- editing a control ---------------------------------------------------------------------------------------
def _set_edit(app, on):
    pads.let_go(app)
    app._pads_edit = bool(on)
    app._pads_sel = None
    dpg.configure_item(SIDE, show=bool(on))
    dpg.configure_item("pads_area", width=-px(SIDE_W + 8) if on else -1)     # the panel beside the grid, editing
    _fill_banks(app)
    _fill_side(app)


def _sel(app):
    """The selected control, or the selected empty cell as (col, row), or None."""
    s = getattr(app, "_pads_sel", None)
    if isinstance(s, int):
        return pads.find(_st(app), s)
    return s


def labels(app):
    """{label: target} of every action a control can drive: MIDI learn's, then the pads' own."""
    if getattr(app, "_pads_labels", None) is None:
        from native import midi_ui, vj
        out = [(lab, t) for lab, t in midi_ui.targets(app) if t.get("kind") != "pin"]
        for i, d in enumerate(vj.LETTERS):
            out.append((f"VJ {d}: this look (pick it below)", {"kind": "pad_look", "deck": i, "look": ""}))
            out.append((f"VJ {d}: a saved preset (pick it below)", {"kind": "pad_preset", "deck": i, "name": ""}))
        app._pads_labels = out
    return app._pads_labels


def target_label(app, t):
    if not t or not t.get("kind"):
        return "nothing yet - pick an action"
    k = t.get("kind")
    if k == "pad_look":
        return f"VJ {'ABC'[int(t.get('deck', 0))]}: {t.get('look') or '(no look picked)'}"
    if k == "pad_preset":
        return f"VJ {'ABC'[int(t.get('deck', 0))]}: preset {t.get('name') or '(none picked)'}"
    keys = ("kind", "deck", "key")
    for lab, x in labels(app):
        if all(x.get(q) == t.get(q) for q in keys):
            return lab
    return k


def _fill_side(app):
    if not dpg.does_item_exist(SIDE) or not getattr(app, "_pads_edit", False):
        return
    s = _sel(app)
    ctl = isinstance(s, dict)
    dpg.configure_item("pads_s_empty", show=isinstance(s, tuple))
    dpg.configure_item("pads_s_ctl", show=ctl)
    if s is None:
        dpg.set_value("pads_s_title", "Click a cell to add a control, or a control to change it.")
        return
    if isinstance(s, tuple):
        dpg.set_value("pads_s_title", f"Cell {s[0] + 1}, {s[1] + 1}")
        return
    dpg.set_value("pads_s_title", f"{pads.TYPE_WORDS[s['type']]}  ({s['w']} x {s['h']})")
    dpg.set_value("pads_s_type", pads.TYPE_WORDS[s["type"]])
    dpg.set_value("pads_s_label", s.get("label", ""))
    dpg.set_value("pads_s_colour", s.get("colour", "grey"))
    dpg.set_value("pads_s_target", target_label(app, s.get("target")))
    num.set("pads_s_lo", float(s.get("lo", 0.0)))
    num.set("pads_s_hi", float(s.get("hi", 1.0)))
    dpg.set_value("pads_s_invert", bool(s.get("invert")))
    dpg.set_value("pads_s_orient", "vertical" if s.get("orient", "v") == "v" else "horizontal")
    dpg.configure_item("pads_s_orient", show=s["type"] == "fader")
    k = pads.kind_of(s.get("target"))
    dpg.configure_item("pads_s_valrow", show=k == "value")
    dpg.configure_item("pads_s_lookrow", show=k == "look")
    dpg.configure_item("pads_s_presetrow", show=k == "preset")
    if k == "look":
        from native import vj_looks
        dpg.configure_item("pads_s_look", items=sorted(vj_looks.LOOKS))
        dpg.set_value("pads_s_look", s["target"].get("look", ""))
    if k == "preset":
        from native import vj
        dpg.configure_item("pads_s_preset", items=sorted(vj.options(app)["presets"]))
        dpg.set_value("pads_s_preset", s["target"].get("name", ""))
    _fill_actions(app)


def _fits_type(typ, t):
    """Whether an action suits a control: a fader or a knob only moves a value."""
    return typ in pads.BUTTONS or pads.kind_of(t) == "value"


def _fill_actions(app):
    s = _sel(app)
    if not isinstance(s, dict):
        return
    q = (dpg.get_value("pads_s_find") or "").strip().lower()
    items = [lab for lab, t in labels(app) if _fits_type(s["type"], t) and (not q or q in lab.lower())]
    dpg.configure_item("pads_s_actions", items=items)
    now = target_label(app, s.get("target"))
    dpg.set_value("pads_s_actions", now if now in items else "")


def _pick_action(app, lab):
    s = _sel(app)
    t = next((t for l, t in labels(app) if l == lab), None)
    if not isinstance(s, dict) or t is None:
        return
    s["target"] = dict(t)
    _save(app)
    _fill_side(app)


def _target_set(app, **kw):
    s = _sel(app)
    if isinstance(s, dict):
        s["target"].update(kw)
        _save(app)
        _fill_side(app)


def _ctl_set(app, key, v):
    s = _sel(app)
    if not isinstance(s, dict):
        return
    s[key] = v
    if key == "type" and not _fits_type(v, s.get("target")):
        s["target"] = {}                       # a fader cannot fire a cut: picked again
    _save(app)
    _fill_side(app)


def _add_control(app, typ):
    s = _sel(app)
    if not isinstance(s, tuple):
        return
    st = _st(app)
    b = pads.current(st)
    w, h = (1, 2) if typ == "fader" and s[1] + 1 < b["rows"] else (1, 1)
    c = pads.new_control(st, typ, s[0], s[1], w, h)
    if not pads.fits(b, c):
        c["h"] = 1
    b["controls"].append(c)
    app._pads_sel = c["id"]
    _save(app)
    _fill_side(app)


def _remove_control(app):
    s = _sel(app)
    if not isinstance(s, dict):
        return
    b = pads.current(_st(app))
    b["controls"] = [c for c in b["controls"] if c["id"] != s["id"]]
    app._pads_sel = None
    _save(app)
    _fill_side(app)


# --- the grid: drawn and played ---------------------------------------------------------------------------------
def _geometry(app):
    """(x0, y0, cell w, cell h, gap) of the grid on screen, sized to the area it has."""
    b = pads.current(_st(app))
    aw, ah = dpg.get_item_rect_size("pads_area")
    aw, ah = max(px(120), aw - px(4)), max(px(120), ah - px(4))
    dpg.configure_item(GRID, width=int(aw), height=int(ah))
    gap = px(6)
    cw, ch = (aw - gap) / b["cols"], (ah - gap) / b["rows"]
    x0, y0 = dpg.get_item_rect_min(GRID)
    return x0, y0, cw, ch, gap


def _rect(c, cw, ch, gap):
    return (c["x"] * cw + gap, c["y"] * ch + gap, (c["x"] + c["w"]) * cw, (c["y"] + c["h"]) * ch)


def _shade(rgb, k):
    return (int(rgb[0] * k), int(rgb[1] * k), int(rgb[2] * k), 255)


def _draw(app, cw, ch, gap):
    from native import chrome
    st = _st(app)
    b = pads.current(st)
    edit = bool(getattr(app, "_pads_edit", False))
    dpg.delete_item(GRID, children_only=True)
    dpg.draw_rectangle((0, 0), (b["cols"] * cw + gap, b["rows"] * ch + gap), fill=chrome.BG, color=(0, 0, 0, 0),
                       parent=GRID)
    if edit:
        for x in range(b["cols"]):
            for y in range(b["rows"]):
                if pads.at(b, x, y) is None:
                    dpg.draw_rectangle((x * cw + gap, y * ch + gap), ((x + 1) * cw, (y + 1) * ch),
                                       color=(70, 74, 84, 255), rounding=px(6), parent=GRID)
    sel = _sel(app)
    for c in b["controls"]:
        rgb = pads.COLOUR.get(c.get("colour"), pads.COLOUR["grey"])
        x0, y0, x1, y1 = _rect(c, cw, ch, gap)
        on = (not edit) and pads.lit(app, c)
        lab = c.get("label") or target_label(app, c.get("target"))
        if c["type"] in pads.BUTTONS:
            dpg.draw_rectangle((x0, y0), (x1, y1), fill=_shade(rgb, 1.0 if on else 0.32), color=_shade(rgb, 0.9),
                               rounding=px(8), thickness=px(2), parent=GRID)
        else:
            dpg.draw_rectangle((x0, y0), (x1, y1), fill=(28, 31, 38, 255), color=_shade(rgb, 0.7),
                               rounding=px(8), thickness=px(2), parent=GRID)
            f = pads.position(app, c)
            if c["type"] == "fader":
                pad = px(10)
                if c.get("orient", "v") == "v":
                    yb, yt = y1 - pad, y0 + pad + px(16)
                    yf = yb - (yb - yt) * f
                    dpg.draw_rectangle((x0 + pad, yf), (x1 - pad, yb), fill=_shade(rgb, 0.8), color=(0, 0, 0, 0),
                                       rounding=px(4), parent=GRID)
                    dpg.draw_line((x0 + pad, yf), (x1 - pad, yf), color=(240, 240, 240, 255), thickness=px(3),
                                  parent=GRID)
                else:
                    xl, xr = x0 + pad, x1 - pad
                    xf = xl + (xr - xl) * f
                    dpg.draw_rectangle((xl, y0 + pad + px(16)), (xf, y1 - pad), fill=_shade(rgb, 0.8),
                                       color=(0, 0, 0, 0), rounding=px(4), parent=GRID)
                    dpg.draw_line((xf, y0 + pad + px(16)), (xf, y1 - pad), color=(240, 240, 240, 255),
                                  thickness=px(3), parent=GRID)
            else:
                import math
                cx, cy = (x0 + x1) / 2, (y0 + y1) / 2 + px(8)
                r = max(px(8), min(x1 - x0, y1 - y0 - px(16)) / 2 - px(10))
                dpg.draw_circle((cx, cy), r, color=_shade(rgb, 0.5), thickness=px(4), parent=GRID)
                a0, a1 = math.radians(135), math.radians(135 + 270 * f)
                pts = [(cx + r * math.cos(a0 + (a1 - a0) * k / 24), cy + r * math.sin(a0 + (a1 - a0) * k / 24))
                       for k in range(25)]
                dpg.draw_polyline(pts, color=_shade(rgb, 1.0), thickness=px(4), parent=GRID)
                dpg.draw_line((cx, cy), pts[-1], color=(240, 240, 240, 255), thickness=px(3), parent=GRID)
        dpg.draw_text((x0 + px(7), y0 + px(5)), _wrap(lab, x1 - x0 - px(14), 3 if c["type"] in pads.BUTTONS else 1),
                      size=px(14),
                      color=(12, 12, 14, 255) if on and c["type"] in pads.BUTTONS else (232, 234, 238, 255),
                      parent=GRID)
        if edit and isinstance(sel, dict) and sel["id"] == c["id"]:
            dpg.draw_rectangle((x0 - px(2), y0 - px(2)), (x1 + px(2), y1 + px(2)), color=(255, 255, 255, 255),
                               rounding=px(9), thickness=px(2), parent=GRID)
            dpg.draw_rectangle((x1 - px(HANDLE), y1 - px(HANDLE)), (x1, y1), fill=(255, 255, 255, 255),
                               color=(0, 0, 0, 0), parent=GRID)
    if edit and isinstance(sel, tuple):
        x, y = sel
        dpg.draw_rectangle((x * cw + gap, y * ch + gap), ((x + 1) * cw, (y + 1) * ch), color=(255, 255, 255, 255),
                           rounding=px(6), thickness=px(2), parent=GRID)


def _wrap(text, width, lines):
    """The label broken into lines that fit the control's width (about 6.4 px a character at 14 px), at most `lines`,
    the last cut short with dots when the rest does not fit."""
    per = max(3, int(width / px(6.4)))
    out, line = [], ""
    for w in text.split():
        while len(w) > per:                                     # a word longer than the control: broken
            if line:
                out.append(line); line = ""
            out.append(w[:per]); w = w[per:]
        if not line:
            line = w
        elif len(line) + 1 + len(w) <= per:
            line += " " + w
        else:
            out.append(line); line = w
    if line:
        out.append(line)
    if len(out) > lines:
        out = out[:lines]
        out[-1] = (out[-1][:per - 3] if len(out[-1]) > per - 3 else out[-1]) + "..."
    return "\n".join(out)


def _cell(mx, my, x0, y0, cw, ch, b):
    col, row = int((mx - x0) // cw), int((my - y0) // ch)
    if 0 <= col < b["cols"] and 0 <= row < b["rows"]:
        return col, row
    return None


def _travel(c, mx, my, x0, y0, cw, ch, gap):
    """Where on a fader the pointer is, as 0..1 of its travel."""
    rx0, ry0, rx1, ry1 = _rect(c, cw, ch, gap)
    pad = px(10)
    if c.get("orient", "v") == "v":
        yb, yt = y0 + ry1 - pad, y0 + ry0 + pad + px(16)
        return max(0.0, min(1.0, (yb - my) / max(1.0, yb - yt)))
    xl, xr = x0 + rx0 + pad, x0 + rx1 - pad
    return max(0.0, min(1.0, (mx - xl) / max(1.0, xr - xl)))


def poll(app):
    """Each frame while the window is shown: the grid drawn, and the pointer on it played (or, editing, laid out)."""
    if not dpg.does_item_exist(TAG) or not dpg.is_item_shown(TAG):
        if getattr(app, "_pads_drag", None) is not None:
            app._pads_drag = None
            pads.let_go(app)
        return
    if getattr(app, "_pads_project", None) is not app.project:
        app._pads_project = app.project
        app._pads_whole = None
        app._pads_sel = None
        app._pads_labels = None
        _fill_banks(app)
        _fill_side(app)
    x0, y0, cw, ch, gap = _geometry(app)
    st = _st(app)
    b = pads.current(st)
    mx, my = dpg.get_mouse_pos(local=False)
    down = dpg.is_mouse_button_down(dpg.mvMouseButton_Left)
    drag = getattr(app, "_pads_drag", None)
    edit = bool(getattr(app, "_pads_edit", False))
    w, h = dpg.get_item_rect_size(GRID)
    over = x0 <= mx <= x0 + w and y0 <= my <= y0 + h and (dpg.is_item_hovered(GRID) or dpg.is_item_hovered("pads_area"))
    if drag is not None:
        if not down:
            if drag[0] == "play":
                c = pads.find(st, drag[1])
                if c is not None:
                    pads.release(app, c)
            elif drag[0] in ("move", "size"):
                _save(app)
                _fill_side(app)
            app._pads_drag = None
        else:
            _dragging(app, drag, mx, my, x0, y0, cw, ch, gap, b)
    elif over and dpg.is_mouse_button_clicked(dpg.mvMouseButton_Left):
        cell = _cell(mx, my, x0, y0, cw, ch, b)
        if cell is not None:
            c = pads.at(b, *cell)
            if edit:
                if c is None:
                    app._pads_sel = cell
                else:
                    app._pads_sel = c["id"]
                    rx0, ry0, rx1, ry1 = _rect(c, cw, ch, gap)
                    corner = mx >= x0 + rx1 - px(HANDLE) - px(4) and my >= y0 + ry1 - px(HANDLE) - px(4)
                    app._pads_drag = ("size" if corner else "move", c["id"], cell, (c["x"], c["y"]))
                _fill_side(app)
            elif c is not None:
                f = None
                if c["type"] == "fader":
                    f = _travel(c, mx, my, x0, y0, cw, ch, gap)
                elif c["type"] == "knob":
                    app._pads_knob = (my, pads.position(app, c))
                pads.press(app, c, f)
                app._pads_drag = ("play", c["id"])
    _draw(app, cw, ch, gap)


def _dragging(app, drag, mx, my, x0, y0, cw, ch, gap, b):
    st = _st(app)
    c = pads.find(st, drag[1])
    if c is None:
        app._pads_drag = None
        return
    if drag[0] == "play":
        if c["type"] == "fader":
            pads.drag(app, c, _travel(c, mx, my, x0, y0, cw, ch, gap))
        elif c["type"] == "knob":
            y_start, f0 = getattr(app, "_pads_knob", (my, 0.0))
            pads.drag(app, c, f0 + (y_start - my) / px(KNOB_PX))
        return
    col = int((mx - x0) // cw)
    row = int((my - y0) // ch)
    if drag[0] == "move":
        (gc, gr), (ox, oy) = drag[2], drag[3]
        pads.place(b, c, ox + col - gc, oy + row - gr)
    else:
        pads.place(b, c, c["x"], c["y"], max(1, col - c["x"] + 1), max(1, row - c["y"] + 1))
